from __future__ import annotations
from abc import ABC, abstractmethod
from typing import Any, List
from datetime import datetime

class MemoryService(ABC):
    is_async: bool = False

    @abstractmethod
    def clear_user_collection(self, user_id: str) -> None:
        """
        Clears all user memories
        """
        pass

    @abstractmethod
    def add_one(self, user_id: str, payload: Any, timestamp: str) -> dict:
        """
        Adds 1 user memory
        Returns {"status": "success"} 
        """
        pass


    @abstractmethod
    def get_relevant_memories(self, user_id: str, message: str, query_date: datetime, lan: str) -> str:
        """
        Searches relevant user memories based on a message (query) and question date. Returns filled prompt template for an answer containing formatted memories.
        """
        pass

import os
import re
import chromadb

from typing import List, Tuple
from dotenv import load_dotenv

load_dotenv()

PREFIX = os.getenv("CHROMA_PREFIX", "memories_user_")

def connect_chroma():
    host = os.getenv("CHROMA_HOST", "localhost")
    port = int(os.getenv("CHROMA_PORT", "8000"))
    if host:
        return chromadb.HttpClient(host=host, port=port)
    return chromadb.Client()

def extract_user_index(name: str) -> int:
    m = re.match(rf"^{re.escape(PREFIX)}(\d+)$", name)
    return int(m.group(1)) if m else 10**9

def list_collection_names(client) -> List[str]:
    items = client.list_collections()
    names = []
    for it in items:
        if hasattr(it, "name"):
            names.append(it.name)
        else:
            names.append(it.get("name"))
    return names

def get_count(coll) -> int:
    if hasattr(coll, "count"):
        return coll.count()
    batch = coll.get(ids=[], include=[])
    raise RuntimeError("Collection.count() недоступен в клиенте/сервере Chroma.")

def main():
    client = connect_chroma()
    all_names = list_collection_names(client)

    target_names = [n for n in all_names if re.match(rf"^{re.escape(PREFIX)}\d+$", n)]
    if not target_names:
        print(f"Не нашёл коллекции с префиксом '{PREFIX}'.")
        return

    rows: List[Tuple[str, int, int]] = []
    for name in target_names:
        coll = client.get_collection(name=name)
        cnt = get_count(coll)
        rows.append((name, extract_user_index(name), cnt))

    rows.sort(key=lambda x: x[1])

    print("Количество элементов по пользователям (из коллекций Chroma):")
    for name, idx, cnt in rows:
        print(f"{name} (user_{idx}): {cnt}")

if __name__ == "__main__":
    main()

from typing import List, Dict, Optional, Any
from datetime import datetime

from rag.datastore import DataStore

class RagMemorySystem:    
    def __init__(self, model_name: str = "ai-forever/FRIDA"):

        self.model_name = model_name
        self.storage_path = f"./faiss_storage/{self.model_name.replace('/', '__')}"

        self.datastore = DataStore(
            embedder_model_name=self.model_name,
            storage_path=self.storage_path,
        )

    def add_note(self, content: str, time: str = None, user_id: Optional[str] = None):
        metadata = {
            "timestamp": time or datetime.now().isoformat(),
            "user_id": user_id,
        }

        try:
            self.datastore.add(
                message=content,
                user_id=user_id,
                metadata=metadata
            )   
        except Exception as e:
            print(f"Error adding note: {e}")

    def search_memory(self, query: str, limit: int = 10, user_id: Optional[str] = None) -> List[Dict[str, Any]]:
        try:
            search_results = self.datastore.search(
                query=query,
                user_id=user_id, 
                limit=limit
            )

            formatted_results = []
            for result in search_results["results"]:
                formatted_result = {
                    "content": result["memory"],
                    "timestamp": result.get("metadata", {}).get("timestamp", ""),
                    "score": result["score"],
                }
                formatted_results.append(formatted_result)

            return formatted_results

        except Exception as e:
            print(f"Error searching memory: {e}")
            return []

    def clear_user_collection(self, user_id: str) -> None:
        try:
            result = self.datastore.delete_all(user_id=user_id)
            print(f"Cleared collection for user {user_id}: {result}")
        except Exception as e:
            print(f"Error clearing user collection: {e}")

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pandas as pd


def get_latest_dir(output_folder: str, technique_type: str) -> Path:
    root = Path(output_folder) / "details" / technique_type

    if not root.exists():
        raise FileNotFoundError(f"Not found: {root}")

    dirs = [p for p in root.iterdir() if p.is_dir()]
    if not dirs:
        raise FileNotFoundError(f"No subdirs in: {root}")

    return sorted(dirs, key=lambda p: p.name)[-1]


def load_details_df(output_folder: str, technique_type: str) -> pd.DataFrame:
    latest_dir = get_latest_dir(output_folder, technique_type)

    files = sorted(latest_dir.glob("*.parquet"))
    if not files:
        raise FileNotFoundError(f"No parquet in: {latest_dir}")

    return pd.read_parquet(files[-1])


def _cat(doc: Any) -> str | None:
    if not isinstance(doc, dict):
        return None

    spec = doc.get("specific")
    if isinstance(spec, dict) and spec.get("category") is not None:
        return str(spec["category"])

    if doc.get("category") is not None:
        return str(doc["category"])

    return None


def _score(metric: Any, key: str = "llm-judge-accuracy") -> float | None:
    if isinstance(metric, dict):
        v = metric.get(key)
        if v is None:
            return None
        try:
            return float(v)
        except Exception:
            return None
    return None


def build_cat_stats(
    df: pd.DataFrame,
    doc_col: str = "doc",
    metric_col: str = "metric",
    judge_key: str = "llm-judge-accuracy",
) -> pd.DataFrame:
    work = df.copy()

    work["category"] = work[doc_col].apply(_cat)
    work["score"] = work[metric_col].apply(lambda x: _score(x, judge_key))

    work = work.dropna(subset=["category", "score"])

    avg_col = f"avg_{judge_key}"

    stats = (
        work.groupby("category", as_index=False)
        .agg(
            n=("category", "size"),
            **{avg_col: ("score", "mean")},
        )
        .sort_values(["n", avg_col], ascending=[False, False])
        .reset_index(drop=True)
    )

    return stats


def calc_averages(
    stats: pd.DataFrame,
    score_col: str = "avg_llm-judge-accuracy",
    weight_col: str = "n",
) -> tuple[float, float]:
    if stats.empty:
        print("No data")
        return 0.0, 0.0

    if score_col not in stats.columns:
        raise ValueError(f"Column '{score_col}' not found in DataFrame")

    if weight_col not in stats.columns:
        raise ValueError(
            f"Column '{weight_col}' not found in DataFrame. Available columns: {list(stats.columns)}"
        )

    values = stats[score_col]
    weights = stats[weight_col]

    total_weight = weights.sum()
    weighted_avg = (values * weights).sum() / total_weight if total_weight else 0.0
    macro_avg = values.mean()

    return float(weighted_avg), float(macro_avg)


def append_summary_rows(
    stats: pd.DataFrame,
    score_col: str = "avg_llm-judge-accuracy",
    weight_col: str = "n",
) -> pd.DataFrame:
    if stats.empty:
        return stats.copy()

    weighted_avg, macro_avg = calc_averages(
        stats=stats,
        score_col=score_col,
        weight_col=weight_col,
    )

    total_n = int(stats[weight_col].sum())

    summary_rows = pd.DataFrame(
        [
            {
                "category": "TOTAL",
                weight_col: total_n,
                score_col: None,
            },
            {
                "category": "WEIGHTED_AVG",
                weight_col: None,
                score_col: weighted_avg,
            },
            {
                "category": "MACRO_AVG",
                weight_col: None,
                score_col: macro_avg,
            },
        ]
    )

    return pd.concat([stats, summary_rows], ignore_index=True)


def save_cat_json(
    stats: pd.DataFrame,
    output_folder: str,
    technique_type: str,
    filename: str = "category_avg_score.json",
    round_digits: int = 8,
) -> Path:
    latest_dir = get_latest_dir(output_folder, technique_type)

    score_cols = [c for c in stats.columns if c.startswith("avg_")]
    if not score_cols:
        raise ValueError(f"No avg_* column found in stats. Columns: {list(stats.columns)}")

    score_col = score_cols[0]

    normal_rows = stats[~stats["category"].isin(["TOTAL", "WEIGHTED_AVG", "MACRO_AVG"])].copy()

    total_n = int(normal_rows["n"].sum()) if not normal_rows.empty else 0
    weighted_avg, macro_avg = calc_averages(
        normal_rows,
        score_col=score_col,
        weight_col="n",
    )

    rows = []
    for _, row in normal_rows.iterrows():
        n_val = row["n"]
        score_val = row[score_col]

        rows.append(
            {
                "category": str(row["category"]),
                "n": int(n_val),
                score_col: round(float(score_val), round_digits),
            }
        )

    data = {
        "summary": {
            "total_n": total_n,
            "weighted_avg": round(float(weighted_avg), round_digits),
            "macro_avg": round(float(macro_avg), round_digits),
        },
        "rows": rows,
    }

    out_path = latest_dir / filename
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

    return out_path

import time
from datetime import datetime
import chromadb
from typing import Any
from jinja2 import Template
from cortex.memory_system import AgenticMemorySystem
from cortex.constants import DEFAULT_STM_CAPACITY, DEFAULT_LLM_BACKEND, DEFAULT_EMBEDDING_MODEL, DEFAULT_LLM_MODEL
from evaluation.prompts import ANSWER_PROMPT_RU, ANSWER_PROMPT_EN
from .interface import MemoryService


class CortexService(MemoryService):

    is_async = False

    def __init__(self, embedder: str = DEFAULT_EMBEDDING_MODEL, top_k: int = 10):
        self.memory_system = AgenticMemorySystem(
            model_name=embedder,
            llm_backend=DEFAULT_LLM_BACKEND,
            llm_model=DEFAULT_LLM_MODEL,
            stm_capacity=DEFAULT_STM_CAPACITY,
            enable_smart_collections=True,
            enable_background_processing=False,
        )
        self.top_k = top_k

    def clear_user_collection(self, user_id: str) -> None:
        client = chromadb.PersistentClient(path="./chromadb_data")
        col_name = f"memories_{user_id}"
        if any(c.name == col_name for c in client.list_collections()):
            client.delete_collection(name=col_name)
            print(f"Deleted {user_id} collection")

    def add_one(self, user_id: str, payload: Any, timestamp: str) -> dict:
        proccessed_timestamp = CortexService.add_day_info_to_timestamp(timestamp)
        if isinstance(payload, list):
            payload = "\n".join([f"{m['role']}: {m['content']}" for m in payload])
        self.memory_system.add_note(content=payload, time=proccessed_timestamp, user_id=user_id)

        return {"status": "success"}

    def search(self, user_id: str, query: str, query_date=None, top_k: int = 10, max_retries=3, retry_delay=1, temporal_weight=None):
        retries = 0

        analyzed_query = self.memory_system.analyze_content(query)
        temporal_weight = 0.0  # Pure semantic search by default

        while retries < max_retries:
            try:
                # Search only in LTM as specified in requirements
                content_memories = self.memory_system.search_memory(
                    query=query,
                    user_id=user_id,
                    memory_source="ltm",  # Search only in LTM
                    limit=top_k // 2,
                    temporal_weight=temporal_weight
                )

                # If we have keywords from analysis, use them as an additional search
                keywords = analyzed_query.get("keywords", [])
                if keywords:
                    keyword_query = " ".join(keywords)
                    keyword_memories = self.memory_system.search_memory(
                        query=keyword_query,
                        user_id=user_id,  # Properly use the user_id
                        memory_source="ltm",
                        limit=top_k                    
                    )

                    # Combine and deduplicate results
                    combined_memories = content_memories.copy()
                    content_ids = {m["id"] for m in content_memories}
                    for memory in keyword_memories:
                        if memory["id"] not in content_ids:
                            combined_memories.append(memory)

                    # Trim if we have more than top_k combined results
                    memories = combined_memories[:top_k]
                else:
                    memories = content_memories

                break
            except Exception as e:
                print(f"Search error (attempt {retries + 1}): {e}")
                retries += 1
                if retries >= max_retries:
                    raise e
                time.sleep(retry_delay)

        # Format memories for response
        formatted_memories = []

        for memory in memories:
            memory_dict = {
                'memory': memory["content"],
                'timestamp': memory["timestamp"],
                'score': round(memory.get("score", 0.0), 2),
                'context': memory.get("context", ""),
                'keywords': memory.get("keywords", []),
                'tags': memory.get("tags", [])
            }
            formatted_memories.append(memory_dict)

        return formatted_memories

    def get_relevant_memories(self, user_id: str, message: str, query_date: datetime, lan: str) -> str:
        search_results = self.search(user_id, message, query_date, self.top_k)
        memories = CortexService.compose_search_context(search_results)

        prompt = ANSWER_PROMPT_RU if lan == "ru" else ANSWER_PROMPT_EN
        template = Template(prompt)
        return template.render(
            memories=memories,
            question=message,
            query_date=query_date,
            query_weekday=query_date.strftime('%A') if query_date else ""
        )

    @staticmethod
    def compose_search_context(memories):
        return [f"{item['timestamp']}: {item['memory']}" for item in memories]

    @staticmethod
    def add_day_info_to_timestamp(timestamp):
        day = CortexService.extract_day_from_timestamp(timestamp)
        day_info = f" ({day})" if day else ""
        final_timestamp = timestamp + day_info
        return final_timestamp

    @staticmethod
    def extract_day_from_timestamp(timestamp):
        if not isinstance(timestamp, str):
            return None

        try:
            if "(" in timestamp and ")" in timestamp:
                day_part = timestamp.split("(")[-1].split(")")[0].strip()
                if day_part:
                    return day_part

            try:
                from datetime import datetime
                parsed_dt = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
                return parsed_dt.strftime("%A")
            except (ValueError, AttributeError):
                pass

            if "on" in timestamp:
                parts = timestamp.split("on")
                if len(parts) > 1:
                    date_part = parts[1].strip()
                    if "(" in date_part:
                        date_part = date_part.split("(")[0].strip()

                    from datetime import datetime
                    date_formats = [
                        "%d %B, %Y",
                        "%B %d, %Y",
                        "%d-%m-%Y",
                        "%Y-%m-%d",
                    ]

                    for fmt in date_formats:
                        try:
                            date_obj = datetime.strptime(date_part, fmt)
                            return date_obj.strftime("%A")
                        except ValueError:
                            continue

        except Exception as e:
            print(f"Could not parse timestamp: {timestamp} - {e}")

        return None
